# -*- coding: utf-8 -*-
"""دفعة 3 — تحديث 3 مقالات (11 صحيفة جنائية / 12 نقل القيد / 15 منصة مصر الرقمية)
بحث ويب جديد موثق في sources-log.md بتاريخ 1/10/2026 — كل رقم من مصدرين على الأقل.
Atomic patch: يفشل كله أو ينفع كله — بدون تعديل جزئي."""
import re, sys, shutil

PATH = "articles.html"
BAK = "articles.html.bak-batch3"

UPDATES = {
    "إزاي تستخرج صحيفة حالة جنائية؟":
        r"""<h3>📋 الخطوات (أونلاين)</h3><p>1. ادخل <a href=\"https://ecriminal.gov.eg\" target=\"_blank\">بوابة الأدلة الجنائية</a> (أو دليل خدمات <a href=\"https://moi.gov.eg\" target=\"_blank\">موقع الداخلية</a> ← الأدلة الجنائية)</p><p>2. اختار «إصدار صحيفة الحالة الجنائية المميكنة» وسجّل الدخول أو اعمل حساب جديد</p><p>3. املأ بياناتك (القومي — الاسم — العنوان) واضغط «تسجيل الطلب»</p><p>4. ادفع الرسوم إلكترونيًا (بطاقة أو فوري أو محفظة)</p><p>5. التنفيذ خلال 72 ساعة والاستلام من مندوب البريد بعد التحقق من بطاقتك</p><h3>📄 المستندات</h3><p>• صورة شخصية حديثة 4×6</p><p>• بطاقة الرقم القومي (أو جواز سفر ساري — شهادة ميلاد لمن دون 15 سنة — بطاقة إقامة للأجانب)</p><h3>💰 الرسوم</h3><p>• عادي ~75ج (استلام 4-5 أيام) — مستعجل 100-150ج (24-72 ساعة وممكن نفس اليوم في مكاتب الأقسام) — أونلاين ~50ج + توصيل بريد 40-60ج</p><h3>⏰ مهم</h3><p>• لازم تكون بصماتك العشرية مسجلة بالأحوال المدنية</p><p>• التقديم والاستلام شخصيين — الفيش موجه لجهة واحدة فقط — وصلاحيته 3 شهور من الإصدار</p><h3>💡 نصيحة</h3><p>احتفظ برقم الطلب بعد الدفع لتتبعه أونلاين</p>""",
    "إزاي تنقل قيدك لمحافظة تانية؟":
        r"""<h3>📋 الخطوات</h3><p>1. روح لمكتب السجل المدني التابع لإقامتك الجديدة (البطاقة الجديدة بتطلع منه)</p><p>2. اشتري استمارة بطاقة واملأها بالعنوان الجديد بدقة</p><p>3. قدّم الاستمارة والمستندات وسدّد الرسوم</p><p>4. استلم بطاقتك حسب فئة الاستمارة — وبعض الحالات ممكن تبدأ أونلاين من <a href=\"https://cso.moi.gov.eg\" target=\"_blank\">بوابة الأحوال المدنية</a> بس التوقيع غالبًا حضوري</p><h3>📄 المستندات</h3><p>• البطاقة الحالية (صورة + الأصل للاطلاع)</p><p>• إثبات العنوان الجديد: عقد تمليك موثق — أو عقد إيجار موثق (مع حضور المؤجر للتصديق) — أو إيصال مرافق حديث (كهرباء/مياه/غاز/تليفون) باسمك</p><p>• لو ساكن مع قريب: إقرار منه + بطاقته + ما يثبت القرابة</p><p>• الزوجة لعنوان زوجها: صورة بطاقة الزوج (+ وثيقة الزواج عند بعض المكاتب)</p><h3>💰 الرسوم</h3><p>نفس فئات استمارات البطاقة: عادية 50ج (15 يوم) — عاجلة 125ج (3 أيام) — خاصة 175ج (24 ساعة) — VIP إكسبريس 515ج (30 دقيقة)</p><h3>⏰ مهم</h3><p>قانون الأحوال المدنية 143/1994 (م.48) بيديك 3 شهور بس لتحديث بياناتك بعد تغيير سكنك — بعدها غرامة 50ج</p><h3>💡 نصيحة</h3><p>بعد نقل قيدك افتكر تنقل بطاقة التموين من <a href=\"https://digital.gov.eg\" target=\"_blank\">بوابة مصر الرقمية</a> عشان تفضل تصرف من محافظتك الجديدة</p>""",
    "إزاي تسجّل في منصة مصر الرقمية؟":
        r"""<h3>📋 الخطوات</h3><p>1. ادخل على <a href=\"https://digital.gov.eg\" target=\"_blank\">digital.gov.eg</a> ودوس «إنشاء حساب جديد»</p><p>2. اكتب الرقم القومي + رقم المصنع المدوّن على البطاقة + الاسم الأول لأمك واضغط «تحقق» (لو عندك أكتر من بطاقة من التجديد استخدم رقم المصنع في الأحدث)</p><p>3. اكتب رقم موبايلك المسجل باسمك — هيوصلك كود SMS من 6 أرقام</p><p>4. اكتب الكود واضغط «التالي»</p><p>5. اعمل كلمة سر قوية (حروف إنجليزية كبيرة وصغيرة + أرقام) — والبريد الإلكتروني اختياري</p><p>6. سجّل دخولك بعد كده بالموبايل أو الرقم القومي وكلمة السر</p><h3>⚠️ الشروط</h3><p>• موبايل مسجل باسمك شخصيًا (بيستقبل كود التفعيل)</p><p>• بياناتك متطابقة مع بطاقة الرقم القومي — خاصة الاسم الأول لأمك</p><h3>🛠️ أشهر الخدمات</h3><p>التموين (استعلام وبدل فاقد ونقل بين المحافظات) — المرور (تجديد الرخصة والمخالفات) — الأحوال المدنية (شهادات ميلاد ووفاة وقيد عائلي) — التوثيق والشهر العقاري — القضايا والمحاكم — التأمينات — الضرائب العقارية — السجل التجاري</p><h3>💡 نصيحة</h3><p>نزّل تطبيق «مصر الرقمية» من Google Play أو App Store بنفس حسابك — إشعارات فورية لطلباتك وسداد إلكتروني</p>""",
}

src = open(PATH, encoding="utf-8").read()
shutil.copyfile(PATH, BAK)
count_before = src.count("title:'")
problems = []
lengths = {}
for title, new_content in UPDATES.items():
    esc = re.escape(title)
    pattern = re.compile(r"(title:'" + esc + r"'.*?content:`)[^`]*(`)", re.DOTALL)
    if len(pattern.findall(src)) != 1:
        problems.append(title); continue
    src = pattern.sub(lambda m: m.group(1) + new_content + m.group(2), src, count=1)
    lengths[title] = len(new_content)

if problems:
    open(PATH, "w", encoding="utf-8").write(open(BAK, encoding="utf-8").read())
    sys.exit("فشل التطابق لمقالات: " + ", ".join(problems) + " — تم التراجع")

if src.count("title:'") != count_before or src.count("content:`") != count_before:
    sys.exit("عدد المقالات اتغير! — لم يتم الحفظ")

open(PATH, "w", encoding="utf-8").write(src)
checks = ["صحيفة الحالة الجنائية المميكنة", "صلاحيته 3 شهور من الإصدار",
          "بصماتك العشرية مسجلة", "قانون الأحوال المدنية 143/1994 (م.48)",
          "غرامة 50ج", "VIP إكسبريس 515ج", "نقل بطاقة التموين",
          "رقم المصنع المدوّن على البطاقة", "كود SMS من 6 أرقام",
          "الاسم الأول لأمك"]
print("OK — تم تحديث 3 مقالات، عدد المقالات الكلي:", count_before)
for t, L in lengths.items():
    print(f"  طول محتوى {t!r}: {L} حرف")
for c in checks:
    print(("✓ " if c in src else "✗ مفقود ") + c)
